        'function loadChapter(){title.textContent="章评";tabs.style.display="none";api("/v1/reader/render-ext",{bookId:BID,chapterId:CID},function(err,root){if(err){showError(err);return;}var outer=root.data||{},d=outer.data||{},ext=d.bookChapterExtInfo||{},ps=(ext.paragraphList||[]).slice(0),total=0;for(var i=0;i<ps.length;i++)total+=Number(ps[i].commentCount||0);subtitle.textContent="本章共 "+total+" 条段评";ps.sort(function(a,b){return Number(b.commentCount||0)-Number(a.commentCount||0);});ps=ps.slice(0,6);if(!ps.length){list.innerHTML="<div class=\\"empty\\">本章暂无评论</div>";return;}list.innerHTML="";for(var x=0;x<ps.length;x++)(function(item){var section=document.createElement("section"),pid=String(item.paragraphId||("p"+Number(item.orderId||0))),count=Number(item.commentCount||0);section.className="section";section.innerHTML="<h2>第 "+(Number(item.orderId||0)+1)+" 段 · "+count+" 条</h2><div class=\\"loading\\">加载中...</div>";list.appendChild(section);api("/v1/comments/chapter-list",{bookId:BID,chapterId:CID,paragraphId:pid,order:"hot",size:5},function(e,res){if(e){section.innerHTML+="<div class=\\"error\\">加载失败</div>";return;}var o=res.data||{},dd=o.data||{},arr=dd.commentList||[],html=section.querySelector("h2").outerHTML;for(var z=0;z<arr.length;z++)html+=cardHtml(arr[z]);section.innerHTML=html;wire(section);});})(ps[x]);});}',
